UPDATE "Setting"
SET
  "fireSafetyRules" = '[{"id":"report","titleRu":"Сообщите о пожаре","titleKz":"Өрт туралы хабарлаңыз","textRu":"Позвоните 101 или 112, назовите точный адрес и место возгорания.","textKz":"101 немесе 112 нөміріне қоңырау шалып, нақты мекенжай мен өрт орнын айтыңыз."},{"id":"warn","titleRu":"Предупредите людей","titleKz":"Адамдарды ескертіңіз","textRu":"Нажмите кнопку пожарной сигнализации и спокойно сообщите окружающим.","textKz":"Өрт дабылы түймесін басып, айналадағы адамдарға сабырмен хабарлаңыз."},{"id":"leave","titleRu":"Покиньте здание","titleKz":"Ғимараттан шығыңыз","textRu":"Идите к ближайшему эвакуационному выходу, закрывая за собой двери. Не пользуйтесь лифтом.","textKz":"Есіктерді артыңыздан жауып, жақын эвакуациялық шығу жолына барыңыз. Лифтіні пайдаланбаңыз."},{"id":"help","titleRu":"Помогите другим","titleKz":"Басқаларға көмектесіңіз","textRu":"По возможности помогите детям, пожилым людям и людям с инвалидностью.","textKz":"Мүмкіндігінше балаларға, қарттарға және мүгедектігі бар адамдарға көмектесіңіз."},{"id":"stay-outside","titleRu":"Не возвращайтесь","titleKz":"Қайтып кірмеңіз","textRu":"Ожидайте пожарных снаружи и выполняйте указания ответственных лиц.","textKz":"Өрт сөндірушілерді сыртта күтіп, жауапты адамдардың нұсқауын орындаңыз."}]'::jsonb,
  "fireSafetyWarningRu" = 'При задымлении двигайтесь пригнувшись и прикройте рот и нос влажной тканью.',
  "fireSafetyWarningKz" = 'Түтін болған жағдайда еңкейіп қозғалыңыз және ауыз-мұрныңызды дымқыл матамен жабыңыз.';
